// PrepareEvent canonicalizes an event before delivery and reports whether it should be persisted.
func PrepareEvent(event Event) (Event, bool) {
	event.Kind = strings.ToLower(strings.TrimSpace(event.Kind))
	return event, event.Kind != "probe"
}

arguments.body:
event, deliver := audit.PrepareEvent(event)
	if !deliver {
		return nil
	}
	return d.sink.Write(event)

for _, event := range events {
		event, deliver := audit.PrepareEvent(event)
		if !deliver {
			continue
		}
		if err := sink.Write(event); err != nil {
			return err
		}
	}
	return nil

for _, event := range events {
		event, deliver := audit.PrepareEvent(event)
		if !deliver {
			continue
		}
		if err := sink.Write(event); err != nil {
			return err
		}
	}
	return nil

event, deliver := PrepareEvent(event)
	if !deliver {
		return nil
	}
	if err := f.First.Write(event); err != nil {
		return err
	}
	return f.Second.Write(event)

event, deliver := PrepareEvent(event)
	if !deliver {
		return nil
	}
	m.Events = append(m.Events, event)
	return nil

for _, event := range b.queue {
		event, deliver := PrepareEvent(event)
		if !deliver {
			continue
		}
		if err := b.Sink.Write(event); err != nil {
			return err
		}
	}
	return nil

event, deliver := audit.PrepareEvent(event)
	if !deliver {
		return nil
	}
	j.Entries = append(j.Entries, event)
	return nil

